// Filters modal
const filtersModal = document.querySelector('.filters-modal')
const filtersBtn = document.querySelector('.catalog-products-header__filter-btn')

const closeFiltersModal = () => {
	filtersModal.classList.remove('filters-modal--active')
	darken.classList.remove('darken--active')
	document.body.classList.remove('popup-open')
}

filtersBtn.addEventListener('click', event => {
	event.stopPropagation()
	filtersModal.classList.add('filters-modal--active')
	darken.classList.add('darken--active')
	document.body.classList.add('popup-open')
	filtersModal.style.top = 'unset'
})

document.addEventListener('click', event => {
	if (filtersModal.classList.contains('filters-modal--active') && isClickOutside(filtersModal, event)) {
		closeFiltersModal()
	}
})

const filtersModalCurtain = document.querySelector('.filters-modal__curtain-wrapper')

///////////////////////

let startY = 0
let newStartY = 0

filtersModalCurtain.addEventListener(
	'touchstart',
	event => {
		event.preventDefault()

		const touch = event.touches[0]
		startY = touch.clientY - filtersModal.getBoundingClientRect().top
	},
	{ passive: false }
)

// Событие: перемещение
filtersModalCurtain.addEventListener(
	'touchmove',
	event => {
		event.preventDefault()
		const touch = event.touches[0]

		const newTop = touch.clientY - startY

		newStartY = touch.clientY - filtersModal.getBoundingClientRect().top

		if (newTop > 0) {
			filtersModal.style.top = newTop + 'px'
		} else {
			filtersModal.style.top = 0 + 'px'
		}
		if (newTop < window.screen.height - filtersModal.getBoundingClientRect().height) {
			filtersModal.style.top = 'unset'
		}
	},
	{ passive: false }
)

filtersModalCurtain.addEventListener('touchend', () => {
	if (newStartY > startY) {
		closeFiltersModal()
	}
	if (filtersModal.getBoundingClientRect().top > window.screen.height / 2) {
		closeFiltersModal()
	}
})

///////////////////////

// Open / Close
const catalogDescLink = document.querySelector('.catalog-products-bottom .toggle-text')
const catalogDescText = document.querySelector('.catalog-products-bottom__text')

catalogDescLink.addEventListener('click', () => {
	catalogDescText.classList.toggle('catalog-products-bottom__text--open')
})

// Mobile categories slider
let catalogCategoriesSwiper = null;

const initCatalogSwiper = (width) => {

    const categoriesSwiperWrapper = document.querySelector('.catalog-categories-swiper.swiper');
    if (!categoriesSwiperWrapper) {
        return;
    }

    // 1. Сначала DESTROY
    if (catalogCategoriesSwiper) {
        catalogCategoriesSwiper.destroy(true, true);
        catalogCategoriesSwiper = null;
    }

    // 2. Сбрасываем стили
    const swiperWrapper = categoriesSwiperWrapper.querySelector('.swiper-wrapper');
    const slides = categoriesSwiperWrapper.querySelectorAll('.swiper-slide');

    if (swiperWrapper) {
        swiperWrapper.style.cssText = '';
    }

    slides.forEach(slide => {
        slide.style.cssText = '';
    });

    // 3. ПРИНУДИТЕЛЬНО устанавливаем ширину контейнера
    categoriesSwiperWrapper.style.cssText = `width: ${width}px !important; max-width: ${width}px !important;`;

    // 4. Форсируем reflow
    void categoriesSwiperWrapper.offsetWidth;

    // 5. Вычисляем slidesPerView
    const slideWidth = 120;
    const spaceBetween = 8;
    const slidesPerView = width / (slideWidth + spaceBetween);

    // ✅ 6. Находим scrollbar
    const scrollbarEl = document.querySelector('.catalog-categories-swiper-scrollbar');
    
    // Очищаем scrollbar перед инициализацией
    if (scrollbarEl) {
        scrollbarEl.innerHTML = '';
        scrollbarEl.classList.remove('swiper-scrollbar-horizontal');
    }

    // 7. Создаём swiper
    catalogCategoriesSwiper = new Swiper('.catalog-categories-swiper', {
        slidesPerView: slidesPerView > 1 ? slidesPerView : 4,
        spaceBetween: 8,
        slidesOffsetAfter: 0,
        slidesOffsetBefore: 0,
        watchOverflow: true,
        grabCursor: true,
        // ✅ Scrollbar с draggable
        scrollbar: {
            el: scrollbarEl,
            draggable: true,
            snapOnRelease: false,
            hide: false,
        },
    });

    console.log('✅ Catalog categories swiper создан');
}

const calculateSwiperWidth = () => {
    const catalogWrapperRect = document.querySelector('.catalog__wrapper')?.getBoundingClientRect();
    const filtersRect = document.querySelector('.catalog__wrapper .filters')?.getBoundingClientRect();
    const categoriesSwiperContainerRect = document.querySelector('.catalog-section .container')?.getBoundingClientRect();

    if (!categoriesSwiperContainerRect) return null;

    let newWidth;
    const isMobile = window.matchMedia('(max-width: 768px)').matches;

    if (isMobile) {
        newWidth = categoriesSwiperContainerRect.width - 40;
    } else {
        if (catalogWrapperRect && filtersRect) {
            newWidth = catalogWrapperRect.width - filtersRect.width - 20;
        } else {
            newWidth = categoriesSwiperContainerRect.width;
        }
    }

    return newWidth;
}

const fixMobileCategoriesSlider = () => {
    const width = calculateSwiperWidth();

    if (!width) {
        return;
    }

    initCatalogSwiper(width);
}


// При ресайзе
let catalogResizeTimer;
window.addEventListener('resize', () => {
    clearTimeout(catalogResizeTimer);
    catalogResizeTimer = setTimeout(() => {
        fixMobileCategoriesSlider();
    }, 300);
});

// Первая инициализация
console.log('🚀 Первый запуск');
fixMobileCategoriesSlider();

// При ресайзе — БЕЗ пересоздания swiper, только update
let resizeTimer;
window.addEventListener('resize', () => {
	clearTimeout(resizeTimer);
	resizeTimer = setTimeout(() => {
		console.log('⏰ RESIZE');
		fixMobileCategoriesSlider();
	}, 300);
});

// Dropdown
const dropdown = document.querySelector('.catalog-products-header__btn')
const dropdownContent = document.querySelector('.catalog-products-header__btn-content')
const dropdownWrapper = document.querySelector('.catalog-products-header__btn-wrapper')

dropdown.addEventListener('click', () =>
	dropdownWrapper.classList.toggle('catalog-products-header__btn-wrapper--active')
)

dropdownContent.addEventListener('click', e => {
	const currentDataSort = e.target
	dropdown.querySelector('p').textContent = currentDataSort.textContent
	dropdownWrapper.classList.remove('catalog-products-header__btn-wrapper--active')
})

document.addEventListener('click', e => {
	if (isClickOutside(dropdownWrapper, e)) {
		dropdownWrapper.classList.remove('catalog-products-header__btn-wrapper--active')
	}
})
